import React, { useMemo, useState } from 'react';
import type {
  BankStatementImportRow,
  BatchDetailLine,
  BankStatementImportVoucher,
  CreateBankStatementImportVoucherRequest,
} from '../../../../../services/kt/bankStatementImportModels';
import { bankStatementImportService } from '../../../../../services/kt/bankStatementImportService';
import { getApiErrorMessage } from '../../../../../utils/getApiErrorMessage';
import type { ReconcileStatementBatchLink } from '../Step1Upload/BatchReconcilePanel';
import styles from './StepCreateImp.module.css';

function formatAmount(n: number): string {
  return n.toLocaleString('vi-VN');
}

function getCurrentMonthCode(): string {
  const d = new Date();
  return `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}`;
}

interface Props {
  statementRows: BankStatementImportRow[];
  batchDetails: { file: File; lines: BatchDetailLine[] }[];
  bankStatementFileCount: number;
  batchFileCount: number;
  /** Map từ tab Đối soát (lô ↔ mã GD). */
  reconcileLinks?: ReconcileStatementBatchLink[];
  onCreated: (voucher: BankStatementImportVoucher) => void;
  onBack: () => void;
}

const StepCreateImp: React.FC<Props> = ({
  statementRows,
  batchDetails,
  bankStatementFileCount,
  batchFileCount,
  reconcileLinks = [],
  onCreated,
  onBack,
}) => {
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [defaultBankAccountCode, setDefaultBankAccountCode] = useState('1121');
  const [importedByEmployeeCode, setImportedByEmployeeCode] = useState('');
  const [importedByName, setImportedByName] = useState('');
  const [detailTab, setDetailTab] = useState<'statement' | 'batch' | 'link'>('statement');

  const totals = useMemo(() => {
    let credit = 0;
    let debit = 0;
    let fee = 0;
    let tax = 0;
    for (const r of statementRows) {
      credit += r.creditAmount ?? 0;
      debit += r.debitAmount ?? (r.creditAmount ? 0 : r.amount ?? 0);
      fee += r.feeAmount ?? 0;
      tax += r.taxAmount ?? 0;
    }
    return { credit, debit, fee, tax };
  }, [statementRows]);

  const showFeeTax = totals.fee > 0 || totals.tax > 0;

  const allBatchLines = useMemo(
    () => batchDetails.flatMap(d => d.lines),
    [batchDetails],
  );

  const links = useMemo(() => {
    const out: CreateBankStatementImportVoucherRequest['links'] = [];
    const seen = new Set<string>();
    const add = (l: CreateBankStatementImportVoucherRequest['links'][number]) => {
      const key = `${l.statementImportReference ?? l.statementRowIndex}|${l.batchRef}`;
      if (seen.has(key)) return;
      seen.add(key);
      out.push(l);
    };

    // 1) Map từ tab Đối soát (ưu tiên — lô có thể gồm nhiều GD Thu+Chi)
    for (const l of reconcileLinks) {
      const row = statementRows.find(r =>
        (l.statementImportReference && r.importReference === l.statementImportReference)
        || (l.statementReferenceCode && r.referenceCode === l.statementReferenceCode)
        || r.rowIndex === l.statementRowIndex,
      );
      // Giữ link kể cả tạm thiếu row (seed lại theo ref) — tránh mất Thu đã chọn
      add({
        statementRowIndex: row?.rowIndex ?? l.statementRowIndex,
        statementImportReference: row?.importReference ?? l.statementImportReference,
        statementReferenceCode: row?.referenceCode ?? l.statementReferenceCode,
        batchRef: l.batchRef,
      });
    }

    // 2) Auto / manual refs trên dòng sao kê
    for (const r of statementRows) {
      const refs = [
        ...(r.detectedBatchRefs ?? []),
        ...(r.manualBatchRef ? [r.manualBatchRef] : []),
      ];
      for (const batchRef of refs) {
        if (!batchRef) continue;
        add({
          statementRowIndex: r.rowIndex,
          statementImportReference: r.importReference,
          statementReferenceCode: r.referenceCode,
          batchRef,
        });
      }
    }
    return out;
  }, [statementRows, reconcileLinks]);

  const handleCreate = async () => {
    setSaving(true);
    setError(null);
    try {
      const payload: CreateBankStatementImportVoucherRequest = {
        importedByEmployeeCode: importedByEmployeeCode || undefined,
        importedByName: importedByName || undefined,
        defaultBankAccountCode,
        monthCode: getCurrentMonthCode(),
        fileCount: bankStatementFileCount + batchFileCount,
        statementLines: statementRows.map(r => ({
          rowIndex: r.rowIndex,
          transactionDate: r.transactionDate,
          referenceCode: r.referenceCode,
          amount: r.amount,
          debitAmount: r.debitAmount,
          creditAmount: r.creditAmount,
          feeAmount: r.feeAmount,
          taxAmount: r.taxAmount,
          counterpartyName: r.counterpartyName,
          description: r.description,
          bankAccountCode: r.bankAccountCode,
          partnerBankName: r.partnerBankName,
          importReference: r.importReference,
          expenseNote: r.expenseNote,
          suggestedVoucherType: r.suggestedVoucherType,
          detectedBatchRefs: r.detectedBatchRefs,
          customerCode: r.customerCode,
        })),
        batchLines: allBatchLines.map((l, i) => ({
          lineIndex: l.lineIndex ?? i,
          batchRef: l.batchRef,
          beneficiaryName: l.beneficiaryName,
          accountNumber: l.accountNumber,
          bankName: l.bankName,
          amount: l.amount,
          ftNumber: l.ftNumber,
          description: l.description,
          status: l.status,
          sheetDate: l.sheetDate,
          staffNote: l.staffNote,
          sourcePath: l.sourcePath,
          companyCode: l.companyCode,
        })),
        links,
      };
      const voucher = await bankStatementImportService.createImportVoucher(payload);
      onCreated(voucher);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Không tạo được chứng từ IMP'));
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={styles.root} data-testid="kt-import-sao-ke-step-create-imp">
      <div className={styles.headerCard}>
        <div className={styles.headerTitle}>Tạo import</div>
        <div className={styles.headerGrid}>
          <label>
            <span>Số chứng từ</span>
            <input value="(tự sinh sau khi Lưu)" readOnly className={styles.ro} />
          </label>
          <label>
            <span>Người import (mã NV)</span>
            <input
              value={importedByEmployeeCode}
              onChange={e => setImportedByEmployeeCode(e.target.value.toUpperCase())}
              placeholder="Mã NV — default từ login (bổ sung lookup)"
            />
          </label>
          <label>
            <span>Tên NV</span>
            <input
              value={importedByName}
              onChange={e => setImportedByName(e.target.value)}
              placeholder="Tên nhân viên"
            />
          </label>
          <label>
            <span>Thời gian</span>
            <input value={new Date().toLocaleString('vi-VN')} readOnly className={styles.ro} />
          </label>
          <label>
            <span>TK ngân hàng (ĐK)</span>
            <input
              value={defaultBankAccountCode}
              onChange={e => setDefaultBankAccountCode(e.target.value)}
            />
          </label>
          <label>
            <span>Mức xử lý</span>
            <input value="1 — Draft" readOnly className={styles.ro} />
          </label>
        </div>
      </div>

      <div className={styles.tabs}>
        <button type="button" className={detailTab === 'statement' ? styles.tabActive : styles.tab} onClick={() => setDetailTab('statement')}>
          Sao kê ({statementRows.length})
        </button>
        <button type="button" className={detailTab === 'batch' ? styles.tabActive : styles.tab} onClick={() => setDetailTab('batch')}>
          Thanh toán lô ({allBatchLines.length})
        </button>
        <button type="button" className={detailTab === 'link' ? styles.tabActive : styles.tab} onClick={() => setDetailTab('link')}>
          Link Sao kê – lô ({links.length})
        </button>
      </div>

      <div className={styles.gridWrap}>
        {detailTab === 'statement' && (
          <table className={styles.table}>
            <thead>
              <tr>
                <th>#</th>
                <th>Ngày</th>
                <th>Đối tượng</th>
                <th>Số tiền</th>
                {showFeeTax && <th>Phí</th>}
                {showFeeTax && <th>Thuế</th>}
                <th>Nội dung</th>
                <th>Chứng từ gốc</th>
              </tr>
            </thead>
            <tbody>
              {statementRows.slice(0, 200).map((r, i) => (
                <tr key={r.rowIndex}>
                  <td>{i + 1}</td>
                  <td>{r.transactionDate || '—'}</td>
                  <td>{r.counterpartyName || '—'}</td>
                  <td className={styles.money}>{formatAmount(r.creditAmount || r.debitAmount || r.amount || 0)}</td>
                  {showFeeTax && (
                    <td className={styles.money}>{r.feeAmount ? formatAmount(r.feeAmount) : '—'}</td>
                  )}
                  {showFeeTax && (
                    <td className={styles.money}>{r.taxAmount ? formatAmount(r.taxAmount) : '—'}</td>
                  )}
                  <td>{r.description || '—'}</td>
                  <td className={styles.path}>{r.importReference || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {detailTab === 'batch' && (
          <table className={styles.table}>
            <thead>
              <tr>
                <th>#</th>
                <th>Mã lô</th>
                <th>Thụ hưởng</th>
                <th>Số tiền</th>
                <th>Chứng từ gốc</th>
              </tr>
            </thead>
            <tbody>
              {allBatchLines.slice(0, 200).map((l, i) => (
                <tr key={`${l.batchRef}-${l.lineIndex}-${i}`}>
                  <td>{i + 1}</td>
                  <td>{l.batchRef || '—'}</td>
                  <td>{l.beneficiaryName || '—'}</td>
                  <td className={styles.money}>{formatAmount(l.amount)}</td>
                  <td className={styles.path}>{l.sourcePath || '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
        {detailTab === 'link' && (
          <table className={styles.table}>
            <thead>
              <tr>
                <th>#</th>
                <th>Dòng SK</th>
                <th>Mã GD (FT)</th>
                <th>Chứng từ gốc</th>
                <th>Mã lô</th>
              </tr>
            </thead>
            <tbody>
              {links.slice(0, 200).map((l, i) => (
                <tr key={`${l.statementRowIndex}-${l.batchRef}-${i}`}>
                  <td>{i + 1}</td>
                  <td>{l.statementRowIndex}</td>
                  <td>{l.statementReferenceCode || '—'}</td>
                  <td className={styles.path}>{l.statementImportReference || '—'}</td>
                  <td>{l.batchRef}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className={styles.footer}>
        <div className={styles.footerStats}>
          <span>Tổng file: <b>{bankStatementFileCount + batchFileCount}</b></span>
          <span>Thu: <b className={styles.credit}>{formatAmount(totals.credit)}</b></span>
          <span>Chi: <b className={styles.debit}>{formatAmount(totals.debit)}</b></span>
          {showFeeTax && (
            <>
              <span>Phí: <b>{formatAmount(totals.fee)}</b></span>
              <span>Thuế: <b>{formatAmount(totals.tax)}</b></span>
            </>
          )}
        </div>
        {error && <div className={styles.error}>{error}</div>}
        <div className={styles.footerActions}>
          <button type="button" className={styles.btnSecondary} onClick={onBack} disabled={saving}>Quay lại</button>
          <button type="button" className={styles.btnPrimary} onClick={handleCreate} disabled={saving || statementRows.length === 0}>
            {saving ? 'Đang tạo…' : 'Tạo import'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default StepCreateImp;
