/**
 * GD sao kê được phép gắn với thanh toán lô.
 *
 * Đối soát (danh sách chính): chỉ hub — **không đối tượng**.
 * Tab Giao dịch (default): Chi cùng ngày không ĐT · Thu/Chi cùng mã ref.
 * «Hiện tất cả»: mọi GD cùng file.
 */

import type { BankStatementImportRow } from '../services/kt/bankStatementImportModels';
import { extractBulkRefsFromDescription, normalizeBulkRef } from './extractBatchRefs';

function normText(s?: string): string {
  return String(s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toUpperCase();
}

/** Key hoàn tiền / hoàn trả trên sao kê (MB refund failed batch leg). */
export function isHoanTienStatementRow(row: Pick<BankStatementImportRow, 'description' | 'referenceCode'>): boolean {
  const blob = normText(`${row.description ?? ''} ${row.referenceCode ?? ''}`);
  return /HOAN\s*TIEN|HOAN\s*TRA|HOAN\s*LAI|REFUND/.test(blob);
}

export function hasStatementCounterparty(row: Pick<BankStatementImportRow, 'counterpartyName' | 'partnerBankName'>): boolean {
  const hasCounterparty = !!(row.counterpartyName && row.counterpartyName.trim());
  const hasPartnerBank = !!(row.partnerBankName && row.partnerBankName.trim());
  return hasCounterparty || hasPartnerBank;
}

/** Thiếu đối tác + NH đối tác → hub aggregate / pool — hiện trên danh sách đối soát. */
export function isBatchHubCandidate(row: Pick<BankStatementImportRow, 'counterpartyName' | 'partnerBankName'>): boolean {
  return !hasStatementCounterparty(row);
}

/** Có mã ref lô (bulk / INHOUSE) trong mô tả — «mã ref chung». */
export function hasSharedBulkRef(row: Pick<BankStatementImportRow, 'description' | 'detectedBatchRefs'>): boolean {
  if ((row.detectedBatchRefs?.length ?? 0) > 0) return true;
  return extractBulkRefsFromDescription(row.description).length > 0;
}

/** Tập ref chuẩn hoá của 1 GD (detected + extract mô tả + referenceCode). */
export function collectStatementBulkRefs(row: Pick<BankStatementImportRow, 'description' | 'detectedBatchRefs' | 'referenceCode'>): Set<string> {
  const out = new Set<string>();
  for (const r of row.detectedBatchRefs ?? []) {
    const n = normalizeBulkRef(r);
    if (n) out.add(n);
  }
  for (const r of extractBulkRefsFromDescription(row.description)) {
    const n = normalizeBulkRef(r);
    if (n) out.add(n);
  }
  const code = row.referenceCode?.trim();
  if (code) {
    const n = normalizeBulkRef(code);
    if (n) out.add(n);
  }
  return out;
}

function setsIntersect(a: Set<string>, b: Set<string>): boolean {
  for (const x of a) {
    if (b.has(x)) return true;
  }
  return false;
}

/**
 * Tab Giao dịch — mặc định (không «Hiện tất cả»):
 * 1) Chi · cùng ngày · không đối tượng (hub)
 * 2) Thu/Chi có cùng mã ref với GD chính hoặc lô đang chọn
 */
export function isDefaultPickerTxCandidate(
  row: BankStatementImportRow,
  main: BankStatementImportRow,
  opts: {
    sameDateKey: string;
    rowDateKey: string;
    selectedBatchRefs: string[];
  },
): boolean {
  const debit = row.debitAmount ?? 0;
  const credit = row.creditAmount ?? 0;
  if (debit <= 0 && credit <= 0 && (row.amount ?? 0) === 0) return false;

  // (1) Chi hub cùng ngày không ĐT
  if (debit > 0 && isBatchHubCandidate(row) && opts.rowDateKey && opts.rowDateKey === opts.sameDateKey) {
    return true;
  }

  // (2) Cùng mã ref với GD chính hoặc lô đã chọn
  const mainRefs = collectStatementBulkRefs(main);
  for (const br of opts.selectedBatchRefs) {
    const n = normalizeBulkRef(br);
    if (n) mainRefs.add(n);
  }
  if (mainRefs.size === 0) return false;
  const rowRefs = collectStatementBulkRefs(row);
  return setsIntersect(mainRefs, rowRefs);
}

/**
 * GD được chọn ở tab Giao dịch khi «Hiện tất cả» / link rộng.
 */
export function isBatchLinkableStatementRow(row: BankStatementImportRow): boolean {
  if (isBatchHubCandidate(row)) return true;
  if (isHoanTienStatementRow(row)) return true;
  if (hasSharedBulkRef(row)) return true;
  if ((row.creditAmount ?? 0) > 0) return true;
  return false;
}

/** Hướng tiền: Chi hoặc Thu. */
export function isBatchLinkableMoneyDirection(row: BankStatementImportRow): boolean {
  const debit = row.debitAmount ?? 0;
  const credit = row.creditAmount ?? 0;
  if (debit > 0) return true;
  if (credit > 0) return true;
  return (row.amount ?? 0) !== 0;
}

/** Số tiền ký: Chi cộng · Thu trừ. */
export function gdSignedAmountForBatchMatch(row: BankStatementImportRow): number {
  const debit = row.debitAmount ?? 0;
  const credit = row.creditAmount ?? 0;
  if (debit > 0) return debit;
  if (credit > 0) return -credit;
  return row.amount || 0;
}

export function gdDisplayAmount(row: BankStatementImportRow): number {
  return Math.abs(gdSignedAmountForBatchMatch(row));
}

/** Prefer Chi hub làm main khi seed links. */
export function pickBatchGroupMainIndex(
  idxs: number[],
  resolve: (idx: number) => BankStatementImportRow | undefined,
): number {
  const uniq = [...new Set(idxs)];
  if (uniq.length === 0) return -1;
  if (uniq.length === 1) return uniq[0];

  const scored = uniq.map(idx => {
    const r = resolve(idx);
    let score = 0;
    if (r) {
      if ((r.debitAmount ?? 0) > 0) score += 100;
      if (isBatchHubCandidate(r)) score += 40;
      if ((r.creditAmount ?? 0) > 0) score -= 20;
    }
    return { idx, score };
  });
  scored.sort((a, b) => b.score - a.score || a.idx - b.idx);
  return scored[0].idx;
}

export function findStatementRowForLink(
  rows: BankStatementImportRow[],
  link: {
    statementRowIndex: number;
    statementImportReference?: string;
    statementReferenceCode?: string;
  },
): BankStatementImportRow | undefined {
  const byRef = link.statementImportReference?.trim();
  if (byRef) {
    const hit = rows.find(r => (r.importReference ?? '').trim() === byRef);
    if (hit) return hit;
  }
  const byCode = link.statementReferenceCode?.trim();
  if (byCode) {
    const hit = rows.find(r => (r.referenceCode ?? '').trim() === byCode);
    if (hit) return hit;
  }
  return rows.find(r => r.rowIndex === link.statementRowIndex);
}

/** Thu = xanh · Chi = vàng (không dùng đỏ cho loại GD). */
export const GD_COLOR_THU = '#15803d';
export const GD_COLOR_CHI = '#ca8a04';

export function gdMoneyColor(row: Pick<BankStatementImportRow, 'debitAmount' | 'creditAmount'>): string {
  if ((row.debitAmount ?? 0) > 0) return GD_COLOR_CHI;
  if ((row.creditAmount ?? 0) > 0) return GD_COLOR_THU;
  return '#334155';
}
