import type { PostingReasonInitItem } from '../../../../../services/voucherInit/endpoint';

/** TK Nợ/Có khớp TK NH (equal hoặc prefix — vd. 1121 / 11211). */
export function accountMatchesBankAccount(
  accountCode: string | null | undefined,
  bankAccountCode: string,
): boolean {
  const a = (accountCode ?? '').trim();
  const b = bankAccountCode.trim();
  if (!a || !b) return false;
  return a === b || a.startsWith(b) || b.startsWith(a);
}

/**
 * Chỉ reason có Nợ hoặc Có gắn TK ngân hàng (default **1121**).
 * GAP-IMP-VOUCHER-15 / Step 2li.
 */
export function filterPostingReasonsByBankAccount(
  rules: PostingReasonInitItem[],
  bankAccountCode: string,
): PostingReasonInitItem[] {
  const bank = bankAccountCode.trim();
  if (!bank) return rules;
  return rules.filter(r => {
    const debit = r.erpDebitAccountCode || r.debitAccountCode;
    const credit = r.erpCreditAccountCode || r.creditAccountCode;
    return accountMatchesBankAccount(debit, bank) || accountMatchesBankAccount(credit, bank);
  });
}
