/**
 * Trạng thái dòng thanh toán lô (MB bulk) — parity REVA `isMbBatchSuccessStatus`.
 * Chỉ «Thành công» tham gia sum khớp tiền với sao kê; «Thất bại» tách riêng.
 */

function normStatus(s?: string): string {
  return String(s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .trim()
    .toUpperCase();
}

/** true = Thành công (hoặc trống). false = Thất bại / Failed / Lỗi. */
export function isBatchLineSuccess(statusRaw?: string): boolean {
  const n = normStatus(statusRaw);
  if (!n) return true;
  if (n.includes('THAT BAI') || n.includes('FAILED') || n.includes('LOI')) return false;
  return n.includes('THANH CONG') || n.includes('SUCCESS');
}

export function sumBatchLineAmounts(lines: { amount: number; status?: string }[]): {
  successAmount: number;
  failedAmount: number;
  totalAmount: number;
  successCount: number;
  failedCount: number;
} {
  let successAmount = 0;
  let failedAmount = 0;
  let successCount = 0;
  let failedCount = 0;
  for (const l of lines) {
    const amt = Number(l.amount) || 0;
    if (isBatchLineSuccess(l.status)) {
      successAmount += amt;
      successCount += 1;
    } else {
      failedAmount += amt;
      failedCount += 1;
    }
  }
  return {
    successAmount,
    failedAmount,
    totalAmount: successAmount + failedAmount,
    successCount,
    failedCount,
  };
}

/**
 * Path chứng từ gốc lô: `{file}:tab:{tab}:{line}`
 * — file = relative path; tab = tên sheet Excel (csv → `csv`); line = 1-based row trên sheet.
 */
export function formatBatchSourcePath(
  filePath: string,
  tabName: string,
  lineNo: number,
): string {
  const file = filePath.replace(/\\/g, '/').trim() || 'unknown';
  const tab = String(tabName || 'csv').replace(/:/g, '_').trim() || 'csv';
  const line = Math.max(1, Math.floor(lineNo) || 1);
  return `${file}:tab:${tab}:${line}`;
}

/** Parse `{file}:tab:{tab}:{line}` — null nếu không đúng format. */
export function parseBatchSourcePath(sourcePath?: string): {
  file: string;
  tab: string;
  line: number;
} | null {
  if (!sourcePath) return null;
  const m = sourcePath.trim().match(/^(.*):tab:(.*):(\d+)$/i);
  if (!m) return null;
  return { file: m[1], tab: m[2], line: Number(m[3]) };
}
